import sys
import time

def main():
    start_time = time.time()

    # Initialize input and output
    input_data = sys.stdin.read().splitlines()
    input_iter = iter(input_data)
    def get_token():
        return next(input_iter)

    def get_int():
        return int(get_token())

    def get_char_array():
        return list(get_token())

    # Read input
    n = get_int()
    sequence_chars = get_char_array()

    v_count = 0
    k_count = 0
    x_count = 0

    for i in range(len(sequence_chars)):
        if sequence_chars[i] == 'V':
            v_count += 1
        elif sequence_chars[i] == 'K':
            k_count += 1
        else:
            sequence_chars[i] = 'X'
            x_count += 1

    INF = 10**7
    # Initialize DP table
    dp_table = [[[[INF for _ in range(3)] for _ in range(x_count + 1)] for _ in range(k_count + 1)] for _ in range(v_count + 1)]
    for i in range(3):
        dp_table[0][0][0][i] = 0

    def compute_cost(arr, target, v, k, x):
        cost = 0
        for c in arr:
            if c == 'V':
                v -= 1
                if v == 0 and target == 'V':
                    return cost
                if v < 0:
                    cost += 1
            elif c == 'K':
                k -= 1
                if k == 0 and target == 'K':
                    return cost
                if k < 0:
                    cost += 1
            elif c == 'X':
                x -= 1
                if x == 0 and target == 'X':
                    return cost
                if x < 0:
                    cost += 1
        raise RuntimeError()

    for v in range(v_count + 1):
        for k in range(k_count + 1):
            for x in range(x_count + 1):
                for prev_state in range(3):
                    current_cost = dp_table[v][k][x][prev_state]
                    if current_cost == INF:
                        continue
                    if v + 1 <= v_count:
                        cst = compute_cost(sequence_chars, 'V', v + 1, k, x)
                        if dp_table[v + 1][k][x][0] > current_cost + cst:
                            dp_table[v + 1][k][x][0] = current_cost + cst
                    if k + 1 <= k_count:
                        cst = compute_cost(sequence_chars, 'K', v, k + 1, x)
                        if prev_state != 0:
                            if dp_table[v][k + 1][x][1] > current_cost + cst:
                                dp_table[v][k + 1][x][1] = current_cost + cst
                    if x + 1 <= x_count:
                        cst = compute_cost(sequence_chars, 'X', v, k, x + 1)
                        if dp_table[v][k][x + 1][2] > current_cost + cst:
                            dp_table[v][k][x + 1][2] = current_cost + cst

    answer = min(dp_table[v_count][k_count][x_count])
    print(answer)

    end_time = time.time()
    # Optional: print execution time to stderr
    # print(f"Execution time: {int((end_time - start_time)*1000)} ms", file=sys.stderr)

